    discoveryConsentTitle:["Local behavioral simulation","Simulation comportementale locale"], discoveryConsentHelp:["30 fictional choices sampled from 60 items. No real money, diagnosis or suitability assessment. Your choices and optional confidence remain in the local save. Unsure, skip, and undo are available; participation is optional.","30 choix fictifs tirés de 60 items. Aucun argent réel, diagnostic ou test d’adéquation. Tes réponses et ta confiance facultative restent dans la sauvegarde locale. Tu peux hésiter, passer et annuler ; la participation est facultative."], discoveryConsent:["I agree to this fictional local session.","J’accepte cette session fictive locale."], beginDiscovery:["Begin Discovery →","Commencer Discovery →"], discoveryConsentRequired:["Confirm consent to start the simulation.","Confirme ton consentement pour commencer la simulation."], discoveryQuestion:["Answer Yes to switch, or No to keep your current choice.","Réponds Oui pour changer, ou Non pour garder ton choix actuel."], discoveryProgress:["Discovery progress","Progression du questionnaire"], discoveryStatement:["Imagine your current option is to {b}. Would you switch and {a}?","Pour l’instant, tu peux {b}. Tu veux plutôt {a} ?"], discoveryStyleStatement:["Suppose your usual approach is to {b}. Would you switch and {a}?","Pour gérer tes placements, tu comptes {b}. Tu veux plutôt {a} ?"], discoveryWealthContext:["Starting balance {wealth}","Solde de départ de {wealth}"], discoveryPathStatement:["You start with 100. Your current investment is worth {b}. Would you switch to the investment with these values: {a}?","Tu places 100. Avec ton placement actuel, tu as {b}. Tu veux passer à un placement où tu as {a} ?"], discoveryPathContext:["In either option, each value at one year has a 50% chance. The 0.5% fee is already deducted.","Pour chaque placement, il y a une chance sur deux d’obtenir chacune des deux valeurs après un an. Les frais de 0,5 % sont déjà déduits."], discoveryChanceContext:["If you don’t win, you get nothing in either case.","Avec les deux options, tu ne reçois rien si tu ne gagnes pas."], chooseA:["♥ Yes, switch","♥ Oui, je change"], chooseB:["✕ No, keep it","✕ Non, je garde"], referenceWealth:["Fictional starting wealth","Patrimoine initial fictif"], confidenceOptional:["Confidence in your answers (optional, 1–5)","Confiance dans tes réponses (facultatif, 1–5)"], framingDifferences:["Framing differences","Différences de cadrage"], scoreMethod:["Score = round(1 + 29 × fraction of prudent choices) among 20 scored items. At least 70% resolved responses are required; missing responses produce an extreme-case sensitivity range.","Score = arrondi(1 + 29 × proportion de réponses prudentes) parmi 20 items notés. Au moins 70 % de réponses tranchées sont nécessaires ; les réponses manquantes donnent une plage de sensibilité extrême."], discoverySeparate:["These results do not change your financial loss budget, estimate utility parameters or diagnose a bias. Conditional preferences are not a validated psychological scale.","Ces résultats ne modifient pas ton budget de perte financière, n’estiment pas les paramètres d’utilité et ne diagnostiquent aucun biais. Les préférences conditionnelles ne sont pas une échelle psychologique validée."], risk_tolerance:["Lottery risk choices","Choix de risque en loterie"], loss_sensitivity:["Gain/loss framing choices","Choix face aux gains/pertes"], trajectory_tolerance:["Path and drawdown choices","Choix face aux baisses"], ambiguity:["Ambiguity","Ambiguïté"], time_preference:["Time preference","Préférence temporelle"], management_style:["Management preferences","Préférences de gestion"], risk_tolerance_explain:["Share choosing the certainty alternative","Part des choix de l’alternative certaine"], loss_sensitivity_explain:["Share choosing the less uncertain alternative","Part des choix les moins incertains"], trajectory_tolerance_explain:["Share choosing the smaller modeled drawdown","Part des choix avec la plus faible baisse modélisée"], ambiguity_explain:["Share choosing known probability","Part des choix à probabilité connue"], time_preference_explain:["Share choosing immediate payment","Part des choix du paiement immédiat"], management_style_explain:["Descriptive share of reference B options, not a style scale","Part descriptive des options de référence B, pas une échelle de style"], unknown_card:["Unknown card in this session.","Carte inconnue dans cette session."], invalid_seed:["Invalid session seed.","Graine de session invalide."], invalid_currency:["Unsupported session currency.","Devise de session non prise en charge."], invalid_confidence:["Confidence must be between 1 and 5.","La confiance doit être comprise entre 1 et 5."], invalid_locale:["Invalid response language.","Langue de réponse invalide."],
