    mandateGoals:["Investment goals","Objectifs d’investissement"], addGoal:["+ Add goal","+ Ajouter un objectif"], objective_id:["Objective","Objectif"], goal_due_date:["Target date","Échéance"], goal_amount:["Target amount (optional for preferences)","Montant cible (facultatif pour les préférences)"], goal_currency:["Goal currency","Devise de l’objectif"], goal_basis:["Amount basis","Base du montant"], nominal:["Nominal","Nominal"], real:["Real (today's purchasing power)","Réel (pouvoir d’achat actuel)"], priority:["Priority (1–5; 5 highest)","Priorité (1–5 ; 5 la plus élevée)"], shortfall_penalty:["Relative shortfall penalty","Pénalité relative du déficit"], funding:["Separate funded obligation (not merely a preference)","Besoin financier distinct à financer (pas une simple préférence)"], goalHelp:["Choose from 11 objective types. Dated liabilities and goal-based targets require funded amounts; income targets use periodic withdrawals. Do not duplicate one obligation in goals and flows.","Choisis parmi 11 objectifs. Les passifs datés et objectifs de financement exigent un montant à financer ; les revenus utilisent les retraits périodiques. Ne duplique pas une obligation dans les flux et objectifs."],
    OBJ01:["Capital Preservation","Préservation du capital"], OBJ02:["Income","Revenu"], OBJ03:["Conservative","Prudent"], OBJ04:["Balanced","Équilibré"], OBJ05:["Growth","Croissance"], OBJ06:["Aggressive Growth","Croissance agressive"], OBJ07:["Inflation Protection","Protection contre l’inflation"], OBJ08:["Absolute Return","Rendement absolu"], OBJ09:["Liability-Driven (LDI)","Gestion actif-passif (LDI)"], OBJ10:["Goal-Based","Objectif financier daté"], OBJ11:["Capital Protection","Protection du capital"],
    OBJ01_help:["Limit loss of nominal or real wealth over the chosen horizon; this is not a guarantee.","Limiter la perte de patrimoine nominal ou réel sur l’horizon choisi ; ce n’est pas une garantie."],
    OBJ02_help:["Seek recurring income; enter planned withdrawals in cash flows and an optional annual income target here.","Rechercher un revenu récurrent ; saisis les retraits dans les flux et, si souhaité, un objectif annuel de revenu ici."],
    OBJ03_help:["Prioritize a strict loss and volatility budget over higher growth.","Privilégier un budget strict de perte et de volatilité plutôt qu’une croissance élevée."],
    OBJ04_help:["Seek a trade-off between growth and risk within declared constraints.","Rechercher un compromis entre croissance et risque dans les contraintes déclarées."],
    OBJ05_help:["Target long-term wealth growth; specify a terminal amount if useful.","Viser la croissance patrimoniale à long terme ; préciser un montant terminal si utile."],
    OBJ06_help:["Seek higher growth without automatically increasing the financial loss budget.","Rechercher une croissance plus élevée sans augmenter automatiquement le budget de perte financière."],
    OBJ07_help:["Maintain purchasing power; select real basis and enter inflation if specifying a target.","Préserver le pouvoir d’achat ; choisis la base réelle et saisis l’inflation pour une cible chiffrée."],
    OBJ08_help:["Seek positive net returns relative to a cash benchmark; no promised positive return.","Rechercher un rendement net positif par rapport aux liquidités ; aucun rendement positif garanti."],
    OBJ09_help:["Fund a dated liability. Enter its amount and mark it as a separate funded obligation.","Financer un passif daté. Saisis son montant et marque-le comme besoin distinct à financer."],
    OBJ10_help:["Fund a specific future expense or wealth target. Enter a dated funded amount.","Financer une dépense future ou une cible patrimoniale précise. Saisis un montant daté à financer."],
    OBJ11_help:["Explore a conditional capital floor using a hedge later; protection is neither guaranteed nor implemented here.","Étudier ultérieurement un plancher de capital conditionnel via une couverture ; aucune garantie ni couverture implémentée ici."],
