le:["Unavailable","Indisponible"], no_unique_root:["No unique return","Aucun rendement unique"], ambiguous_cash_flows:["Cash flows may imply multiple returns","Les flux peuvent impliquer plusieurs rendements"], root_outside_range:["Return outside numerical range","Rendement hors plage numérique"], preference_only:["Preference only","Préférence uniquement"], income_not_terminal:["Periodic income, not terminal target","Revenu périodique, pas une cible terminale"], no_funding_goals:["No separate funding goals","Aucun besoin de financement distinct"]
